contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 d, uint256 w) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(d > 0 && w > 0 && w <= d);
        require(address(this).balance >= d);

        c.deposit{value: d}(); if (__ESBMC_reverted()) return;

        uint256 balBeforeWithdraw = address(this).balance;

        bool withdrawReverted;
        c.withdraw(w); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        assert(!withdrawReverted && address(this).balance == balBeforeWithdraw + w);
    }

    receive() external payable {}
}

